/**
 * Check SFTP directory for new or updated files
 * This job is triggered by cron to periodically check for changes
 */

import { list, stat } from '@openfn/language-sftp';
import { fn } from '@openfn/language-common';

// Configuration
const SFTP_DIRECTORY = '/uploads/hiv-indicators/';
const SUPPORTED_EXTENSIONS = ['.xlsx', '.xls'];

list(SFTP_DIRECTORY, (state) => {
  console.log('Checking SFTP directory for new files...');

  // Get previous file tracking from state
  const previousFiles = state.fileTracking || {};
  const currentFiles = {};
  let newFilesFound = false;
  const newFiles = [];

  // Process each file in the directory
  state.data.forEach(file => {
    if (file.type === 'file') {
      const extension = file.name.toLowerCase().substring(file.name.lastIndexOf('.'));

      // Only process supported file types
      if (SUPPORTED_EXTENSIONS.includes(extension)) {
        const fileKey = file.name;
        const fileInfo = {
          name: file.name,
          size: file.size,
          modifiedTime: file.modifiedTime,
          path: SFTP_DIRECTORY + file.name
        };

        currentFiles[fileKey] = fileInfo;

        // Check if this is a new file or has been modified
        const previousFile = previousFiles[fileKey];
        if (!previousFile || 
            previousFile.modifiedTime !== fileInfo.modifiedTime ||
            previousFile.size !== fileInfo.size) {

          console.log(`New or updated file detected: ${fileKey}`);
          newFiles.push(fileInfo);
          newFilesFound = true;
        }
      }
    }
  });

  // Update state with findings
  return {
    ...state,
    newFilesFound,
    newFiles,
    currentFileList: currentFiles,
    lastChecked: new Date().toISOString()
  };
});

// If no new files found, stop the workflow
fn((state) => {
  if (!state.newFilesFound) {
    console.log('No new files found. Workflow will stop here.');
    return {
      ...state,
      workflowComplete: true
    };
  }

  console.log(`Found ${state.newFiles.length} new/updated files to process`);
  return state;
});

/**
 * Download new or updated files from SFTP
 * This job is triggered either after check-sftp-files or directly by webhook
 */

import { get } from '@openfn/language-sftp';
import { fn } from '@openfn/language-common';

// Configuration
const LOCAL_DOWNLOAD_PATH = '/tmp/openfn-downloads/';

fn((state) => {
  console.log('Starting file download process...');

  // Determine files to download
  let filesToDownload = [];

  if (state.newFiles && state.newFiles.length > 0) {
    // From cron check workflow
    filesToDownload = state.newFiles;
    console.log(`Processing ${filesToDownload.length} files from cron check`);
  } else if (state.data && state.data.filePath) {
    // From webhook trigger - single file
    filesToDownload = [{
      name: state.data.fileName || state.data.filePath.split('/').pop(),
      path: state.data.filePath,
      size: state.data.fileSize || null,
      modifiedTime: state.data.modifiedTime || new Date().toISOString()
    }];
    console.log(`Processing single file from webhook: ${filesToDownload[0].name}`);
  } else {
    console.log('No files specified for download');
    return {
      ...state,
      downloadedFiles: [],
      error: 'No files specified for download'
    };
  }

  return {
    ...state,
    filesToDownload,
    downloadedFiles: [],
    downloadStartTime: new Date().toISOString()
  };
});

// Download each file
fn((state) => {
  const downloadPromises = state.filesToDownload.map(async (file, index) => {
    const localPath = `${LOCAL_DOWNLOAD_PATH}${file.name}`;

    console.log(`Downloading ${file.name} to ${localPath}`);

    try {
      // Download the file
      await get(file.path, localPath);

      return {
        ...file,
        localPath,
        downloadTime: new Date().toISOString(),
        status: 'downloaded'
      };
    } catch (error) {
      console.error(`Failed to download ${file.name}:`, error);
      return {
        ...file,
        status: 'failed',
        error: error.message
      };
    }
  });

  return Promise.all(downloadPromises).then(results => {
    const successfulDownloads = results.filter(f => f.status === 'downloaded');
    const failedDownloads = results.filter(f => f.status === 'failed');

    console.log(`Download complete: ${successfulDownloads.length} successful, ${failedDownloads.length} failed`);

    return {
      ...state,
      downloadedFiles: successfulDownloads,
      failedDownloads,
      downloadCompleted: true
    };
  });
});

/**
 * Process Excel data from downloaded SFTP files
 * This job handles the conversion of Excel data to the format expected by generate-dhis2-payload.js
 * Uses configuration-based file type detection and column mapping
 */

import { 
  fn,
  each,
  dataPath,
  dataValue
} from '@openfn/language-common';

import * as XLSX from 'xlsx';
import fs from 'fs';
import { 
  loadFileTypeConfigs, 
  loadMetadataMappings, 
  matchFileToConfig,
  applyColumnMappings 
} from '../../../shared/config-loader.js';

// Enhanced Excel data parsing with configuration
function parseExcelData(filePath, fileName, config, metadata) {
  console.log(`Parsing Excel file: ${fileName} at ${filePath}`);
  console.log(`Using configuration: ${config.fileType}`);

  try {
    // Check if file exists
    if (!fs.existsSync(filePath)) {
      throw new Error(`File not found: ${filePath}`);
    }

    // Read the Excel file
    const workbook = XLSX.readFile(filePath);
    console.log(`Workbook sheets: ${workbook.SheetNames.join(', ')}`);

    let processedData = [];

    if (config.sheetConfig.multiSheet) {
      // Process multiple sheets
      config.sheetConfig.sheetPatterns.forEach(pattern => {
        const matchingSheets = workbook.SheetNames.filter(name => 
          new RegExp(pattern.replace(/\*/g, '.*'), 'i').test(name)
        );

        matchingSheets.forEach(sheetName => {
          const sheetData = processSheet(workbook, sheetName, config, metadata);
          processedData = processedData.concat(sheetData);
        });
      });
    } else {
      // Process single sheet
      const sheetIndex = config.sheetConfig.targetSheet || 0;
      const sheetName = workbook.SheetNames[sheetIndex];
      if (sheetName) {
        processedData = processSheet(workbook, sheetName, config, metadata);
      }
    }

    // Apply validation
    const validation = validateData(processedData, config.dataValidation);
    if (!validation.isValid) {
      console.warn(`Data validation warnings for ${fileName}:`, validation.warnings);
    }

    return {
      type: config.fileType,
      fileName: fileName,
      filePath: filePath,
      config: config,
      data: processedData,
      validation: validation,
      processedAt: new Date().toISOString()
    };

  } catch (error) {
    console.error(`Error parsing Excel file ${fileName}:`, error);
    throw new Error(`Failed to parse Excel file ${fileName}: ${error.message}`);
  }
}

// Process a single sheet with configuration-based mapping
function processSheet(workbook, sheetName, config, metadata) {
  console.log(`Processing sheet: ${sheetName}`);

  const worksheet = workbook.Sheets[sheetName];
  const jsonData = XLSX.utils.sheet_to_json(worksheet, {
    header: config.sheetConfig.headerRow || 1,
    range: (config.sheetConfig.dataStartRow || 2) - 1
  });

  console.log(`Found ${jsonData.length} rows in sheet ${sheetName}`);

  const processedRows = [];

  jsonData.forEach((row, index) => {
    try {
      // Apply column mappings
      const mappedRow = applyColumnMappings(row, config.columnMappings, metadata);

      // Apply transformations
      const transformedRow = applyTransformations(mappedRow, config.transformations);

      // Add metadata
      transformedRow._rowNumber = index + (config.sheetConfig.dataStartRow || 2);
      transformedRow._sheet = sheetName;

      processedRows.push(transformedRow);
    } catch (error) {
      console.warn(`Error processing row ${index + 1} in sheet ${sheetName}:`, error.message);
    }
  });

  return processedRows;
}

// Apply transformations based on configuration
function applyTransformations(row, transformations = []) {
  const transformed = { ...row };

  transformations.forEach(transform => {
    const field = transform.field;
    if (transformed[field] !== undefined) {
      switch (transform.type) {
        case 'numeric':
          let value = transformed[field];
          if (transform.removeCommas) {
            value = value.toString().replace(/,/g, '');
          }
          transformed[field] = parseFloat(value) || transform.defaultValue || 0;
          break;

        case 'dateFormat':
          transformed[field] = transformDate(transformed[field], transform);
          break;

        case 'quarterToMonth':
          transformed[field] = transformQuarter(transformed[field], transform);
          break;

        case 'percentage':
          transformed[field] = transformPercentage(transformed[field], transform);
          break;
      }
    }
  });

  return transformed;
}

// Transform date formats
function transformDate(value, config) {
  if (!value) return value;

  // Simple implementation - would need more robust date parsing
  const date = new Date(value);
  if (!isNaN(date) && config.to === 'YYYYMM') {
    return date.getFullYear().toString() + 
           (date.getMonth() + 1).toString().padStart(2, '0');
  }

  return value;
}

// Transform quarter to month
function transformQuarter(value, config) {
  if (!value) return value;

  // Match patterns like Q1 FY25, Q2FY25, etc.
  const match = value.match(/Q(\d)\s*FY(\d{2})/i);
  if (match) {
    const quarter = parseInt(match[1]);
    const year = 2000 + parseInt(match[2]);
    const fiscalYearStart = config.fiscalYearStart || 1;

    // Calculate the month based on quarter and fiscal year start
    let month = fiscalYearStart + (quarter - 1) * 3;
    let actualYear = year;

    if (month > 12) {
      month = month - 12;
      actualYear = year + 1;
    }

    return actualYear.toString() + month.toString().padStart(2, '0');
  }

  return value;
}

// Transform percentage values
function transformPercentage(value, config) {
  if (!value) return value;

  const numValue = parseFloat(value);
  if (!isNaN(numValue)) {
    if (config.from === 'decimal' && config.to === 'whole') {
      return numValue * 100;
    } else if (config.from === 'whole' && config.to === 'decimal') {
      return numValue / 100;
    }
  }

  return value;
}

// Validate data based on configuration rules
function validateData(data, validationConfig = {}) {
  const warnings = [];
  let isValid = true;

  if (data.length === 0) {
    warnings.push('No data found in the processed file');
    isValid = false;
  }

  const rules = validationConfig.rules || [];

  data.forEach((row, index) => {
    rules.forEach(rule => {
      const value = row[rule.field];

      switch (rule.type) {
        case 'numeric':
          if (typeof value !== 'number' || isNaN(value)) {
            warnings.push(`Row ${row._rowNumber || index}: ${rule.field} must be numeric`);
          } else if (rule.min !== undefined && value < rule.min) {
            warnings.push(`Row ${row._rowNumber || index}: ${rule.field} must be >= ${rule.min}`);
          } else if (rule.max !== undefined && value > rule.max) {
            warnings.push(`Row ${row._rowNumber || index}: ${rule.field} must be <= ${rule.max}`);
          }
          break;

        case 'notEmpty':
          if (!value || value.toString().trim() === '') {
            warnings.push(`Row ${row._rowNumber || index}: ${rule.message || `${rule.field} cannot be empty`}`);
          }
          break;

        case 'regex':
          if (value && !new RegExp(rule.pattern).test(value.toString())) {
            warnings.push(`Row ${row._rowNumber || index}: ${rule.message || `${rule.field} format is invalid`}`);
          }
          break;
      }
    });
  });

  return { isValid: isValid && warnings.length === 0, warnings };
}

// Main processing function
fn((state) => {
  console.log('Starting Excel processing for downloaded files...');

  if (!state.downloadedFiles || state.downloadedFiles.length === 0) {
    console.log('No downloaded files to process');
    return {
      ...state,
      processedFiles: [],
      error: 'No downloaded files to process'
    };
  }

  // Load configurations
  const fileTypeConfigs = loadFileTypeConfigs();
  const metadata = loadMetadataMappings();

  const processedFiles = [];
  const processingErrors = [];

  state.downloadedFiles.forEach(file => {
    try {
      console.log(`Processing file: ${file.name}`);

      // Match file to configuration
      const config = matchFileToConfig(file.name, fileTypeConfigs);

      if (!config) {
        // Fall back to generic processing if no config found
        console.warn(`No configuration found for ${file.name}, using generic processing`);
        // You could implement a generic fallback here
        processingErrors.push({
          fileName: file.name,
          error: 'No matching configuration found'
        });
        return;
      }

      const excelData = parseExcelData(file.localPath, file.name, config, metadata);
      processedFiles.push({
        ...file,
        excelData,
        processedAt: new Date().toISOString(),
        status: 'processed'
      });

      console.log(`Successfully processed: ${file.name} with ${excelData.data.length} rows`);

    } catch (error) {
      console.error(`Failed to process ${file.name}:`, error);
      processingErrors.push({
        fileName: file.name,
        error: error.message
      });
    }
  });

  console.log(`Processing complete: ${processedFiles.length} files processed, ${processingErrors.length} errors`);

  return {
    ...state,
    processedFiles,
    processingErrors,
    processingCompleted: true,
    metadata, // Pass metadata to next job
    data: processedFiles.length > 0 ? processedFiles[0].excelData : null // Primary data for next step
  };
});

/**
 * Generate DHIS2 payload from processed Excel data
 * This job transforms Excel indicator data into DHIS2 dataValueSets format
 * Uses configuration-based metadata mappings
 */

import { fn } from '@openfn/language-common';

function generatePayload(processedFiles, metadata, timeWindow = 3) {
  console.log('Generating DHIS2 payload from processed Excel files...');
  console.log(`Time window for updates: ${timeWindow} months`);

  // Extract all data values from processed files
  const allDataValues = [];
  let totalRecords = 0;

  processedFiles.forEach(file => {
    console.log(`Processing file: ${file.fileName} (${file.excelData.type})`);
    console.log(`File contains ${file.excelData.data.length} data rows`);

    const config = file.excelData.config;

    file.excelData.data.forEach(row => {
      // Create DHIS2 data value from mapped row
      const dataValue = {
        dataElement: row.dataElement,
        orgUnit: row.orgUnit,
        period: row.period,
        value: row.value
      };

      // Add category options if present
      if (row.categoryOptions) {
        // This would need proper category option combo resolution
        // For now, we'll just note them in the data value
        dataValue.categoryOptions = row.categoryOptions;
      }

      // Add attribute options if present
      if (row.attributeOptions) {
        dataValue.attributeOptions = row.attributeOptions;
      }

      // Add comment if present
      if (row.comment) {
        dataValue.comment = row.comment;
      }

      // Add metadata for tracking
      dataValue.sourceFile = file.fileName;
      dataValue.sourceRow = row._rowNumber;

      allDataValues.push(dataValue);
      totalRecords++;
    });
  });

  console.log(`Extracted ${allDataValues.length} data values from ${totalRecords} total records`);

  // Filter data values based on time window
  const currentDate = new Date();
  const cutoffDate = new Date(currentDate);
  cutoffDate.setMonth(cutoffDate.getMonth() - timeWindow);

  const filteredDataValues = allDataValues.filter(dv => {
    // Parse period (assuming YYYYMM format)
    const period = dv.period;
    if (!period || period.length < 6) {
      console.warn(`Invalid period format: ${period}`);
      return false;
    }

    const year = parseInt(period.substring(0, 4));
    const month = parseInt(period.substring(4, 6));

    if (isNaN(year) || isNaN(month)) {
      console.warn(`Cannot parse period: ${period}`);
      return false;
    }

    const periodDate = new Date(year, month - 1);
    const isWithinWindow = periodDate >= cutoffDate;

    if (!isWithinWindow) {
      console.log(`Excluding data value for period ${period} (outside ${timeWindow} month window)`);
    }

    return isWithinWindow;
  });

  console.log(`Filtered to ${filteredDataValues.length} data values within ${timeWindow} months`);

  // Group by dataset if needed
  const dataSetGroups = {};
  filteredDataValues.forEach(dv => {
    // Get dataset from metadata if available
    let dataSetId = 'default';

    if (metadata?.dataElements?.mappings) {
      // Find the data element in metadata to get its dataset
      for (const [category, elements] of Object.entries(metadata.dataElements.mappings)) {
        if (Array.isArray(elements)) {
          const element = elements.find(e => e.dhis2Id === dv.dataElement || e.id === dv.dataElement);
          if (element && element.dataSet) {
            dataSetId = element.dataSet;
            break;
          }
        }
      }
    }

    if (!dataSetGroups[dataSetId]) {
      dataSetGroups[dataSetId] = [];
    }

    // Clean up the data value for DHIS2
    const cleanDataValue = {
      dataElement: dv.dataElement,
      orgUnit: dv.orgUnit,
      period: dv.period,
      value: dv.value
    };

    if (dv.categoryOptionCombo) {
      cleanDataValue.categoryOptionCombo = dv.categoryOptionCombo;
    }

    if (dv.attributeOptionCombo) {
      cleanDataValue.attributeOptionCombo = dv.attributeOptionCombo;
    }

    if (dv.comment) {
      cleanDataValue.comment = dv.comment;
    }

    dataSetGroups[dataSetId].push(cleanDataValue);
  });

  // Create payload
  const payload = {
    dataValueSets: Object.entries(dataSetGroups).map(([dataSetId, dataValues]) => ({
      dataSet: dataSetId !== 'default' ? dataSetId : undefined,
      dataValues: dataValues,
      completeDate: new Date().toISOString(),
      period: new Date().toISOString().substring(0, 7).replace('-', ''),
      orgUnit: 'MW' // Default to Malawi country level, should be configurable
    })),
    metadata: {
      dataSource: 'SFTP Excel Import',
      generatedAt: new Date().toISOString(),
      totalDataValues: filteredDataValues.length,
      originalRecords: totalRecords,
      timeWindowMonths: timeWindow,
      processedFiles: processedFiles.map(f => ({
        fileName: f.fileName,
        type: f.excelData.type,
        recordCount: f.excelData.data.length,
        validation: f.excelData.validation
      }))
    }
  };

  console.log(`Generated DHIS2 payload with ${payload.dataValueSets.length} data value sets`);
  return payload;
}

// Main processing function
fn(state => {
  console.log('Starting DHIS2 payload generation...');

  // Check for processed Excel data
  if (!state.processedFiles || state.processedFiles.length === 0) {
    throw new Error('No processed Excel files found in state. Make sure process-excel-data job executed successfully.');
  }

  // Check for metadata
  if (!state.metadata) {
    console.warn('No metadata found in state. Data element and org unit mappings may not work correctly.');
    state.metadata = {};
  }

  console.log(`Processing ${state.processedFiles.length} Excel files for DHIS2 payload generation`);

  // Get time window from configuration or use default (3 months)
  const timeWindow = state.config?.updateTimeWindow || 3;

  // Generate the DHIS2 payload
  const payload = generatePayload(state.processedFiles, state.metadata, timeWindow);

  // Add processing summary
  const summary = {
    processedAt: new Date().toISOString(),
    filesProcessed: state.processedFiles.length,
    totalDataValues: payload.metadata.totalDataValues,
    dataValueSets: payload.dataValueSets.length,
    errors: state.processingErrors || []
  };

  console.log('Processing Summary:', JSON.stringify(summary, null, 2));

  // Validate payload before sending
  let hasValidationErrors = false;
  payload.dataValueSets.forEach((dvs, index) => {
    dvs.dataValues.forEach((dv, dvIndex) => {
      if (!dv.dataElement) {
        console.error(`Data value set ${index}, value ${dvIndex}: Missing dataElement`);
        hasValidationErrors = true;
      }
      if (!dv.orgUnit) {
        console.error(`Data value set ${index}, value ${dvIndex}: Missing orgUnit`);
        hasValidationErrors = true;
      }
      if (!dv.period) {
        console.error(`Data value set ${index}, value ${dvIndex}: Missing period`);
        hasValidationErrors = true;
      }
      if (dv.value === undefined || dv.value === null) {
        console.error(`Data value set ${index}, value ${dvIndex}: Missing value`);
        hasValidationErrors = true;
      }
    });
  });

  if (hasValidationErrors) {
    console.error('Payload validation errors detected. Review the logs above.');
  }

  console.log('Payload generation completed. Ready for DHIS2 upload.');

  return {
    ...state,
    payload: payload,
    dhis2Payload: payload, // For compatibility
    payloadGeneratedAt: new Date().toISOString(),
    summary: summary
  };
});

/**
 * Upload processed data to DHIS2
 * This job sends the generated dataValueSets payload to DHIS2 via the Web API
 * Supports both single dataValueSet and multiple dataValueSets formats
 */

import { create, fn, each } from '@openfn/language-dhis2';

fn(state => {
  console.log('Starting DHIS2 upload for SFTP-processed data...');

  if (!state.payload) {
    throw new Error('No payload found in state. Ensure the generate-dhis2-payload job executed successfully.');
  }

  console.log('Preparing SFTP-generated payload for DHIS2...');

  // Handle both old format (single dataValueSet) and new format (multiple dataValueSets)
  if (state.payload.dataValueSets) {
    // New format with multiple dataValueSets
    console.log(`Number of data value sets to upload: ${state.payload.dataValueSets.length}`);
    const totalValues = state.payload.dataValueSets.reduce((sum, dvs) => sum + (dvs.dataValues?.length || 0), 0);
    console.log(`Total data values across all sets: ${totalValues}`);
  } else if (state.payload.dataValues) {
    // Old format with single dataValueSet
    console.log(`Number of data values to upload: ${state.payload.dataValues.length}`);
    // Convert to new format for consistency
    state.payload = {
      dataValueSets: [state.payload],
      metadata: state.payload.metadata || {}
    };
  }

  console.log('Data source:', state.payload.metadata?.dataSource || 'SFTP Excel');
  console.log('Generated at:', state.payload.metadata?.generatedAt || new Date().toISOString());

  return state;
});

// Upload each dataValueSet to DHIS2
each("payload.dataValueSets", (state) => {
  const dataValueSet = state.data;
  const index = state.index || 0;

  console.log(`\nUploading data value set ${index + 1}/${state.payload.dataValueSets.length}`);
  console.log(`- Data values: ${dataValueSet.dataValues?.length || 0}`);
  console.log(`- Dataset: ${dataValueSet.dataSet || 'not specified'}`);
  console.log(`- Period: ${dataValueSet.period}`);
  console.log(`- Org Unit: ${dataValueSet.orgUnit}`);

  // Log sample data values for verification
  if (dataValueSet.dataValues?.length > 0) {
    console.log('Sample data values:', dataValueSet.dataValues.slice(0, 2));
  }

  return create("dataValueSets", (state) => {
    // Add metadata for better tracking
    const enhancedPayload = {
      ...dataValueSet,
      completeDate: dataValueSet.completeDate || new Date().toISOString(),
      attribution: {
        source: "SFTP Excel via OpenFn",
        workflow: "HIV-Indicators-SFTP-to-DHIS2-Workflow",
        timestamp: new Date().toISOString(),
        setIndex: index,
        totalSets: state.payload.dataValueSets.length,
        processedFiles: state.payload.metadata?.processedFiles || []
      }
    };

    console.log('Sending enhanced payload to DHIS2...');

    return enhancedPayload;
  })(state);
});

fn(state => {
  console.log('\nAll DHIS2 uploads completed!');

  // Aggregate upload results
  const uploadResults = state.references || [];
  let totalSummary = {
    status: 'completed',
    uploadedAt: new Date().toISOString(),
    totalSets: state.payload.dataValueSets.length,
    totalValues: 0,
    imported: 0,
    updated: 0,
    ignored: 0,
    deleted: 0,
    conflicts: [],
    errors: []
  };

  uploadResults.forEach((result, index) => {
    console.log(`\nResult for data value set ${index + 1}:`, JSON.stringify(result, null, 2));

    if (result && result.importCount) {
      totalSummary.imported += result.importCount.imported || 0;
      totalSummary.updated += result.importCount.updated || 0;
      totalSummary.ignored += result.importCount.ignored || 0;
      totalSummary.deleted += result.importCount.deleted || 0;
    }

    if (result && result.conflicts) {
      totalSummary.conflicts = totalSummary.conflicts.concat(result.conflicts);
    }

    if (result && result.status === 'ERROR') {
      totalSummary.errors.push({
        setIndex: index,
        error: result.description || 'Unknown error'
      });
    }
  });

  // Calculate total values processed
  totalSummary.totalValues = totalSummary.imported + totalSummary.updated + totalSummary.ignored;

  console.log('\nAggregated Upload Summary:', totalSummary);

  if (totalSummary.conflicts.length > 0) {
    console.warn(`Total conflicts: ${totalSummary.conflicts.length}`);
    console.warn('First 5 conflicts:', totalSummary.conflicts.slice(0, 5));
  }

  if (totalSummary.errors.length > 0) {
    console.error(`Total errors: ${totalSummary.errors.length}`);
    totalSummary.errors.forEach(err => {
      console.error(`Set ${err.setIndex + 1} error: ${err.error}`);
    });
  }

  // Store upload results in state for the next job
  return {
    ...state,
    uploadSummary: totalSummary,
    uploadCompleted: true,
    dhis2Responses: uploadResults
  };
});

/**
 * Update file tracking state after successful processing
 * This job updates the tracking information for processed files to avoid reprocessing
 */

import { fn } from '@openfn/language-common';

fn(state => {
  console.log('Updating file tracking state...');

  if (!state.uploadCompleted) {
    console.log('Upload not completed successfully, skipping file tracking update');
    return state;
  }

  // Get current file tracking from state
  const currentFileTracking = state.fileTracking || {};
  const newFileTracking = { ...currentFileTracking };

  // Update tracking for successfully processed files
  if (state.processedFiles && state.processedFiles.length > 0) {
    state.processedFiles.forEach(file => {
      const fileKey = file.name;
      const trackingInfo = {
        name: file.name,
        size: file.size,
        modifiedTime: file.modifiedTime,
        path: file.path,
        processedAt: new Date().toISOString(),
        status: 'processed',
        uploadStatus: state.uploadSummary?.status || 'unknown',
        dhis2Summary: {
          imported: state.uploadSummary?.imported || 0,
          updated: state.uploadSummary?.updated || 0,
          ignored: state.uploadSummary?.ignored || 0
        }
      };

      newFileTracking[fileKey] = trackingInfo;
      console.log(`Updated tracking for file: ${fileKey}`);
    });
  }

  // Update tracking for files checked via cron (mark as checked)
  if (state.currentFileList) {
    Object.entries(state.currentFileList).forEach(([fileKey, fileInfo]) => {
      if (!newFileTracking[fileKey]) {
        // File exists but wasn't processed (no changes detected)
        newFileTracking[fileKey] = {
          ...fileInfo,
          lastChecked: new Date().toISOString(),
          status: 'checked'
        };
      }
    });
  }

  // Clean up old tracking entries (older than 30 days)
  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

  Object.keys(newFileTracking).forEach(fileKey => {
    const fileInfo = newFileTracking[fileKey];
    const fileDate = new Date(fileInfo.processedAt || fileInfo.lastChecked || 0);

    if (fileDate < thirtyDaysAgo) {
      console.log(`Removing old tracking entry for: ${fileKey}`);
      delete newFileTracking[fileKey];
    }
  });

  // Summary of tracking updates
  const trackingSummary = {
    totalTrackedFiles: Object.keys(newFileTracking).length,
    newlyProcessed: state.processedFiles?.length || 0,
    lastUpdated: new Date().toISOString(),
    cleanupPerformed: true
  };

  console.log('File tracking update summary:', trackingSummary);

  // Update state with new file tracking
  return {
    ...state,
    fileTracking: newFileTracking,
    trackingSummary,
    workflowCompleted: true,
    completedAt: new Date().toISOString()
  };
});
